import heapq

def match(orders):
    buy_heap = []   # max-heap by price: store (-price, seq, id)
    sell_heap = []  # min-heap by price: store (price, seq, id)
    orders_info = {}  # id -> dict with side, price, qty remaining, seq, active
    seq_counter = 0
    trades = []

    def add_order(side, oid, price, qty, seq):
        orders_info[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def clean_buy():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, s, oid = sell_heap[0]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                p, s, sell_id = sell_heap[0]
                if typ != 'market' and p > price:
                    break
                sell_info = orders_info[sell_id]
                trade_qty = min(remaining, sell_info['qty'])
                trades.append([oid, sell_id, p, trade_qty])
                remaining -= trade_qty
                sell_info['qty'] -= trade_qty
                if sell_info['qty'] == 0:
                    heapq.heappop(sell_heap)
                clean_sell()
            if typ == 'limit' and remaining > 0:
                add_order('buy', oid, price, remaining, seq)
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': False}
        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                negp, s, buy_id = buy_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                buy_info = orders_info[buy_id]
                trade_qty = min(remaining, buy_info['qty'])
                trades.append([buy_id, oid, p, trade_qty])
                remaining -= trade_qty
                buy_info['qty'] -= trade_qty
                if buy_info['qty'] == 0:
                    heapq.heappop(buy_heap)
                clean_buy()
            if typ == 'limit' and remaining > 0:
                add_order('sell', oid, price, remaining, seq)
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': False}

    return trades

